(() => {
 const q=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)];
 const names=['Stable','Constrained','Recovery'],colors=['#62b9e8','#e9ae52','#7bc7a3'];
 let phase=0,timer=null,h28=[],dataset=[];
 const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const pct=(n,b)=>`${n>=b?'+':''}${((n/b-1)*100).toFixed(1)}% relative to stable`;
 function stop(){clearInterval(timer);timer=null;q('#ev-play').textContent='Play phase sequence';q('#ev-play').setAttribute('aria-pressed','false');}
 function bars(id,key){const max=Math.max(...h28.map(r=>+r[key]));q(id).innerHTML=h28.map((r,i)=>`<button class="ev-bar ${i===phase?'active':''}" data-chart-phase="${i}" aria-pressed="${i===phase}"><span>${names[i]}</span><span class="ev-track"><i style="width:${+r[key]/max*100}%;background:${colors[i]}"></i></span><strong>${(+r[key]).toFixed(4)}</strong></button>`).join('');}
 function selectPhase(i){phase=i;if(!h28.length)return;all('[data-ev-phase]').forEach(b=>b.setAttribute('aria-pressed',+b.dataset.evPhase===i));q('#ev-network').dataset.phase=i;const r=h28[i];q('#ev-rtt').textContent=(+r['RTT ms']).toFixed(4)+' ms';q('#ev-goodput').textContent=(+r['TCP Goodput Mbps']).toFixed(4)+' Mbps';q('#ev-loss').textContent=r['ICMP Loss pct']+'%';q('#ev-rtt-change').textContent=i?pct(+r['RTT ms'],+h28[0]['RTT ms']):'Reference phase mean';q('#ev-goodput-change').textContent=i?pct(+r['TCP Goodput Mbps'],+h28[0]['TCP Goodput Mbps']):'Reference phase mean';q('#ev-phase-description').textContent=[ 'Stable: the reference operational condition.','Constrained: higher measured RTT and lower measured TCP goodput.','Recovery: both phase means return toward the stable values.'][i];bars('#ev-rtt-chart','RTT ms');bars('#ev-goodput-chart','TCP Goodput Mbps');}
 all('[data-ev-phase]').forEach(b=>b.addEventListener('click',()=>{stop();selectPhase(+b.dataset.evPhase);}));
 q('.ev-charts').addEventListener('click',e=>{const b=e.target.closest('[data-chart-phase]');if(b){stop();selectPhase(+b.dataset.chartPhase);}});
 q('#ev-play').addEventListener('click',()=>{if(timer){stop();return;}if(!h28.length)return;if(paused)setMotion(false);q('#ev-network').classList.remove('ev-still');selectPhase(0);q('#ev-play').textContent='Pause phase sequence';q('#ev-play').setAttribute('aria-pressed','true');timer=setInterval(()=>{if(phase===2){stop();return;}selectPhase(phase+1);},3500);});
 const claims=[
 {scope:'H28 / PAPER TABLE VI',title:'The constrained phase changes the measured network response.',body:'Mean RTT rises from 6.0508 to 32.8780 ms; mean TCP bulk goodput falls from 9.2999 to 1.9001 Mbps. Recovery means return toward the reference values.',limit:'Aggregate means support a phase-related response. They do not establish calibrated capacity, precise loss fidelity, or a topology-specific effect.',graphs:[['12_PAPER_H28_RTT.png','Reported H28 mean RTT'],['13_PAPER_H28_goodput.png','Reported H28 mean TCP bulk goodput']],csv:'paper-h28.csv',fields:'Phase · RTT ms · TCP Goodput Mbps · ICMP Loss pct',paper:'Table VI — network-fidelity evaluation'},
 {scope:'H23 / PAPER TABLE IV',title:'The model choice depends on the metric.',body:'Gradient Boosting has the highest reported balanced accuracy (89.58%). Random Forest has the highest recall (87.50%) with a 10% false positive rate. RBF-SVM has zero false positives alongside zero recall: that is not successful detection.',limit:'144 intervals from 16 additional runs; frozen candidates with no retraining or reselection. Within-run correlation and the absence of significance testing limit model ranking claims. The target is synthetic probing, not independently adjudicated malicious traffic.',graphs:[['11_PAPER_H23_Balanced_Accuracy.png','H23 balanced accuracy'],['11_PAPER_H23_Recall.png','H23 recall'],['11_PAPER_H23_FPR.png','H23 false positive rate']],csv:'paper-h23.csv',fields:'Model · Balanced Accuracy · Recall · FPR',paper:'Table IV — frozen-model prospective evaluation'},
 {scope:'H14 / SUPPLIED DATASET EXPORT',title:'Keep the run together when splitting the dataset.',body:'The export contains 216 observations from 24 runs. Training, validation, and test each contain 72 observations from eight runs. Complete run IDs remain in one split. There are 180 class-0 and 36 synthetic-probing observations.',limit:'H14 contains four exported scenario values, while the broader framework describes six workloads. Run-disjoint splitting reduces cross-split run leakage; it does not remove every possible bias or prove generalization to new malicious families.',graphs:[['01_H14_split_sizes.png','H14 split sizes'],['02_H14_label_distribution.png','H14 synthetic label distribution']],csv:'h14.csv',fields:'run_id · split · scenario · phase · interval · label_synthetic_probe · label_scope',paper:'Dataset construction and evaluation methodology; inspect the supplied H14 export for the exact records'}
 ];
 function claim(i){all('[data-ev-claim]').forEach(b=>b.setAttribute('aria-pressed',+b.dataset.evClaim===i));const d=claims[i];q('#ev-claim-detail').innerHTML=`<div class="ev-claim-copy"><span class="explain-kicker">${d.scope}</span><h3>${d.title}</h3><p>${d.body}</p><div class="ev-boundary"><strong>What this does not establish</strong><p>${d.limit}</p></div><dl><dt>Source fields</dt><dd>${d.fields}</dd><dt>Paper reference</dt><dd>${d.paper}</dd></dl><div class="ev-links"><a href="evidence/${d.csv}" download>Download source CSV</a><a href="paper.pdf" target="_blank" rel="noopener">Open paper</a><a href="evidence/original-${i===2?'dataset':'guide'}-package.zip" download>Download original package</a></div></div><div class="ev-original-graphs">${d.graphs.map(([file,title])=>`<a href="evidence/graphs/${file}" target="_blank" rel="noopener"><img src="evidence/graphs/${file}" alt="${title}" loading="lazy"><span>${title} · open full size</span></a>`).join('')}</div>`;}
 all('[data-ev-claim]').forEach(b=>b.addEventListener('click',()=>claim(+b.dataset.evClaim)));
 function run(){const rows=dataset.filter(r=>r.run_id===q('#ev-run').value);if(!rows.length)return;const r=rows[0];q('#ev-run-context').textContent=`${r.split.toUpperCase()} SPLIT · seed ${r.seed} · ${r.topology} topology · ${r.scenario} · ${rows.length} observations`;q('#ev-run-rows').innerHTML=rows.map(r=>`<tr><td>${escape(r.phase)}</td><td>${escape(r.interval)}</td><td>${escape(r.label_synthetic_probe)}</td><td>${(+r.rtt_mean_ms).toFixed(4)}</td><td>${(+r.measured_delivery_mbps).toFixed(4)}</td></tr>`).join('');}
 q('#ev-run').addEventListener('change',run);
 async function fetchText(path){const r=await fetch(path);if(!r.ok)throw Error('Source unavailable');return r.text();}
 Promise.all([fetchText('evidence/paper-h28.csv'),fetchText('evidence/dataset.json')]).then(([csv,json])=>{const lines=csv.trim().split(/\r?\n/),keys=lines.shift().split(',');h28=lines.map(l=>Object.fromEntries(l.split(',').map((v,i)=>[keys[i],v])));dataset=JSON.parse(json).rows;const ids=[...new Set(dataset.map(r=>r.run_id))];q('#ev-run').innerHTML=ids.map(id=>`<option value="${escape(id)}">${escape(id)}</option>`).join('');selectPhase(phase);run();q('#ev-load-status').textContent='Loaded the supplied H28 table and all 216 H14 observations.';}).catch(()=>{q('#ev-load-status').textContent='Some interactive source data could not load. Refresh to retry, or use the source CSV downloads above.';q('#ev-play').disabled=true;});
 function motionState(){q('#ev-network').classList.toggle('ev-still',paused||document.hidden||location.hash!=='#evidence');if(paused||document.hidden||location.hash!=='#evidence')stop();}
 addEventListener('hashchange',motionState);document.addEventListener('visibilitychange',motionState);q('#motion').addEventListener('click',motionState);claim(0);motionState();
})();
